<div class="right_col" role="main"><div class="d-flex justify-content-between mb-3"><h2>Admission Test Seat Plans</h2><a class="btn btn-primary" href="<?= base_url('school/admission/seat-plans/create') ?>">Generate plan</a></div><div class="card shadow-sm"><div class="card-body"><table class="table"><thead><tr><th>Plan</th><th>Test</th><th>School</th><th>Candidates</th><th>Method</th><th>Status</th></tr></thead><tbody><?php foreach($items as $p): ?><tr><td><a href="<?= base_url('school/admission/seat-plans/'.$p->token) ?>"><?= esc($p->title) ?></a></td><td><?= esc($p->test_title) ?></td><td><?= esc($p->school_name) ?></td><td><?= $p->candidate_count ?></td><td><?= esc(ucfirst($p->allocation_method)) ?></td><td><?= $p->is_locked?'Locked':'Generated' ?></td></tr><?php endforeach ?><?php if(!$items): ?><tr><td colspan="6" class="text-center text-muted">No seat plans.</td></tr><?php endif ?></tbody></table></div></div></div>
